mapper.select:

select #{push} time,sum(reject_num) controlNum,sum(monitor_num) monitorNum,sum(c2s_byte_len+s2c_byte_len)*8/300 networkFlowNum,sum(c2s_byte_len)*8/300 upstreamNum,sum(s2c_byte_len)*8/300 downstreamNum,
  sum(new_uni_conn_num) newLinkNum,sum(live_conn_num) activeConNum,sum(drop_conn_num) dropConNum,sum(loop_conn_num) refluxConNum
  from NTC_TOTAL_REPORT
  WHERE report_time >= #{start}
  AND report_time < #{end}


SELECT  #{push} time,entrance_id area,sum(sum) count
FROM ntc_entrance_report
  WHERE report_time >= #{start}
  AND report_time < #{end}
  AND service = 18
group by entrance_id;


        SELECT  #{push} time,service type,SUM(sum)  count
        FROM ntc_service_report
          WHERE report_time >= #{start}
          AND report_time < #{end}
            AND (
          service BETWEEN 16 AND 40
		    or service BETWEEN 258 AND 273
		     or service = 576
        )
        GROUP BY service;


      SELECT  #{push} time,entrance_id area, s_ip src_ip, d_ip dst_ip,service type,SUM(sum) count
	    FROM ntc_service_behav_statistic
          WHERE report_time >= #{start}
          AND report_time < #{end}
	    GROUP BY s_ip,d_ip,service,entrance_id


select max(report_time)
  FROM ntc_total_report
  WHERE report_time < #{end}


select max(report_time)
  FROM ntc_service_behav_statistic
  WHERE report_time < #{end}
